(function () {
  // Match BOTH patterns:
  //  1) div/form with id starting "filters_list_"
  //  2) any element with class 'filter_form' (Joget often uses this)
  var FILTER_HOSTS = '[id^="filters_list_"], .filter_form';

  function stripPluginBootstrap(root) {
    (root || document).querySelectorAll('link[rel="stylesheet"]').forEach(function (lnk) {
      var href = lnk && lnk.href;
      if (href && href.indexOf('TypeAheadMultiSelectSearch/lib/bootstrap.min.css') > -1) {
        lnk.parentNode && lnk.parentNode.removeChild(lnk);
      }
    });
  }

  function enhanceOne(host) {
    if (!host) return;
    // add a stable hook for CSS
    host.classList.add('rm-filters');

    // ensure the dropdown menu has a class even if built lazily
    function tagMenu() {
      var m = host.querySelector('ul.multiselect-container');
      if (m) m.classList.add('rm-ms');
    }
    tagMenu();

    // some plugins build the menu on click
    var btn = host.querySelector('.btn.multiselect, .multiselect.dropdown-toggle');
    if (btn && !btn.__rmBound) {
      btn.__rmBound = true;
      btn.addEventListener('click', function () {
        setTimeout(function () {
          stripPluginBootstrap(document);
          tagMenu();
        }, 0);
      });
    }
  }

  function runAll(ctx) {
    stripPluginBootstrap(ctx);
    (ctx || document).querySelectorAll(FILTER_HOSTS).forEach(enhanceOne);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ runAll(); });
  } else {
    runAll();
  }

  // Re-apply after AJAX (Joget replaces nodes)
  new MutationObserver(function (muts) {
    let need = false;
    for (const m of muts) {
      for (const n of m.addedNodes || []) {
        if (n.nodeType === 1 && (n.matches?.(FILTER_HOSTS) || n.querySelector?.(FILTER_HOSTS))) {
          need = true;
          break;
        }
      }
      if (need) break;
    }
    if (need) runAll();
  }).observe(document.documentElement, { childList: true, subtree: true });
})();



// Avoid to redirect to page by opening new tab
$(document).ready(function() {
    // Override click behavior for userview key formatter links
    $(document).on('click', '.dataList a[href*="/jw/web/userview/"]', function(e) {
        e.preventDefault();

        var href = $(this).attr('href');

        // Clean up duplicate URLs
        if (href.indexOf('/jw/web/userview/') !== href.lastIndexOf('/jw/web/userview/')) {
            var parts = href.split('/jw/web/userview/');
            href = '/jw/web/userview/' + parts[parts.length - 1];
        }

        // Navigate in current window
        window.location.href = href;
    });
});





/* Put this in UI > Settings > Custom Javascript (or Theme > Custom Javascript) */
(function () {
  function onReady(fn){document.readyState!=='loading'?fn():document.addEventListener('DOMContentLoaded',fn);}
  onReady(function () {
    // Find Spring Security login form used by Joget
    var form = document.querySelector('form[action*="spring_security_check"], form[action*="j_spring_security_check"]');
    if (!form) return;

    // Create container + link
    var box = document.createElement('div');
    box.className = 'login-extra';
    var a = document.createElement('a');
    a.href = '#appVariable.currentAppUrl#/userview/AccCreation/su/_/forgotPasswordMenu';              // <-- replace with your public reset page
    a.textContent = 'Forgot password? Reset it';
    a.setAttribute('aria-label', 'Reset your password');

    box.appendChild(a);

    // Place after the submit button (fallback: end of form)
    var submit = form.querySelector('input[type="submit"], button[type="submit"]');
    var target = submit && submit.parentElement ? submit.parentElement : form;
    target.appendChild(box);
  });
})();
